  const contractEl=screen.querySelector('#contract-chip');if(contractEl){const contract=CONTRACTS.find((x)=>x.id===battleSession.contractId),progress=Math.min(contract.target,contractProgress(contract.id,state.history)),complete=progress>=contract.target;contractEl.classList.toggle('complete',complete);contractEl.innerHTML=`<span>${contract.icon} ${t(`contract.${contract.id}`)}</span><b>${complete?'✓':`${progress}/${contract.target}`}</b>`;contractEl.title=t(`contract.effect.${contract.id}`,{target:contract.target});}
